from pathlib import Path
import hashlib,json,os,subprocess,statistics,math
binary=Path('/tmp/logex-checkpoint-modes-candidate-bench')
profiles=[('tiny-history',128,1,'historical',False),('grouped-live-17',17,128,'live',False),('per-block-live-32',32,128,'live',True)]
path=Path('/tmp/logex-checkpoint-modes-results.jsonl')
with path.open('w') as output:
 output.write(json.dumps({'kind':'environment','commit':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'source_diff':subprocess.check_output(['git','diff','--','crates'],text=True),'binary_sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'rustc':subprocess.check_output(['rustc','-Vv'],text=True),'os':subprocess.check_output(['sw_vers'],text=True),'hardware':subprocess.check_output(['sysctl','-n','hw.model','hw.memsize','hw.ncpu'],text=True),'filesystem':subprocess.check_output(['df','-h','/private/tmp'],text=True),'runner_source':Path(__file__).read_text(),'conditions':'Five alternating process pairs x three samples; identical binary and v3 exact row/progress/reopen oracles. Only LOGEX_PUBLICATION_DURABLE_CHECKPOINT differs. Ordered publication allows bounded power-loss rewind; durable confirms latest progress. Fresh directories, OS cache not evicted, no concurrent local audit builds/tests; not physical power-failure or peer throughput evidence.'})+'\n');output.flush()
 for profile,blocks,rows,route,each in profiles:
  for pair in range(5):
   for mode in (['ordered','durable'] if pair%2==0 else ['durable','ordered']):
    env={**os.environ,'LOGEX_PUBLICATION_BLOCKS':str(blocks),'LOGEX_PUBLICATION_ROWS_PER_BLOCK':str(rows),'LOGEX_PUBLICATION_HISTORY_BLOCKS':'2048','LOGEX_PUBLICATION_SEGMENT_ROWS':'1000000','LOGEX_PUBLICATION_WARM_HEADERS':'8192','LOGEX_PUBLICATION_REPEATS':'3','LOGEX_PUBLICATION_HEADER_FIELDS':'minimal','LOGEX_PUBLICATION_ROUTE':route,'LOGEX_PUBLICATION_CHECKPOINT_EACH_BLOCK':str(int(each)),'LOGEX_PUBLICATION_DURABLE_CHECKPOINT':str(int(mode=='durable'))}
    logpath=Path(f'/tmp/logex-checkpoint-modes-{profile}-{pair}-{mode}.log')
    with logpath.open('w') as log:r=subprocess.run(['/usr/bin/time','-l',str(binary),'benchmark_sync_storage_publication','--ignored','--nocapture','--test-threads=1'],env=env,stdout=log,stderr=subprocess.STDOUT)
    if r.returncode:raise RuntimeError(str(logpath))
    for line in logpath.read_text().splitlines():
     if '{' in line:
      try:record=json.loads(line[line.index('{'):])
      except json.JSONDecodeError:continue
      output.write(json.dumps({**record,'profile':profile,'pair':pair,'mode':mode})+'\n')
     elif 'maximum resident set size' in line:output.write(json.dumps({'kind':'rss','profile':profile,'pair':pair,'mode':mode,'bytes':int(line.split()[0])})+'\n')
    output.flush();print(profile,pair,mode,'passed',flush=True)
 records=[json.loads(x)for x in path.read_text().splitlines()]
 for profile,*_ in profiles:
  values={mode:[r['elapsed_ms']for r in records if r.get('kind')=='sample' and r.get('profile')==profile and r.get('mode')==mode] for mode in ['ordered','durable']}
  med={k:statistics.median(v)for k,v in values.items()};summary={'kind':'summary','profile':profile,'median_ms':med,'p95_ms':{k:sorted(v)[math.ceil(.95*len(v))-1]for k,v in values.items()},'durable_extra_ms':med['durable']-med['ordered'],'samples':{k:len(v)for k,v in values.items()}};output.write(json.dumps(summary)+'\n');print(summary,flush=True)
